#include <stdio.h>

typedef struct {
    int x;
    int y;
    int largura;
    int altura;
} Retangulo;

void oRetangulo(int x, int y, int largura, int altura) {
    Retangulo r;
    r.x = x;
    r.y = y;
    r.largura = largura;
    r.altura = altura;
    printf("canto %d %d\n", r.x, r.y);
    printf("tamanho %d %d\n", r.largura, r.altura);
    printf("area %d\n", r.largura * r.altura);
}
